bool MemoryImage::load(const ImageData& proposed) {
    // Shape and vector bounds (the front end checks most of this already).
    uint32_t total_cells = 0;
    for (int s = 0; s < RAM_NUM; ++s) {
        if (proposed.cells[s] > 131072u) return false;
        if ((int)proposed.banks[s].size() != (int)((proposed.cells[s] + 1) / 2)) return false;
        total_cells += proposed.cells[s];
    }
    if (total_cells > 131072u) return false;
    if (proposed.bitmaps.size() > 8193u || proposed.nexthops.size() > 8192u) return false;
    for (size_t i = 0; i < proposed.bitmaps.size(); ++i) {
        if (i && proposed.bitmaps[i - 1] >= proposed.bitmaps[i]) return false;
    }
    if (proposed.root.stage < -1 || proposed.root.stage > 10) return false;
    if (proposed.root.stage < 0 && proposed.root.cell != 0) return false;

    LoadCtx ctx(proposed);
    ctx.slot.resize(RAM_NUM);
    ctx.used.resize(RAM_NUM);
    for (int s = 0; s < RAM_NUM; ++s) {
        ctx.slot[s].assign(proposed.cells[s], -1);
        ctx.used[s].assign(proposed.cells[s], 0);
    }
    ctx.ni_used.assign(proposed.nexthops.size(), 0);
    ctx.pat_used.assign(proposed.bitmaps.size(), 0);

    if (proposed.root.stage >= 0) {
        int i = ctx.decode(proposed.root.stage, proposed.root.cell, 0, 0, 0, 0, false);
        if (i < 0) return false;
        ctx.root_idx = i;
    }
    for (size_t i = 0; i < proposed.front16.size(); ++i) {
        const ImageFront& f = proposed.front16[i];
        uint64_t reghi = (f.key & 0xFFFFull) << 48;
        int idx = ctx.decode(f.loc.stage, f.loc.cell, 16, 16, reghi, 0, false);
        if (idx < 0) return false;
        if (i && proposed.front16[i - 1].key >= f.key) return false;
        ctx.f16.push_back(std::make_pair(f.key, idx));
    }
    for (size_t i = 0; i < proposed.front64.size(); ++i) {
        const ImageFront& f = proposed.front64[i];
        int idx = ctx.decode(f.loc.stage, f.loc.cell, 64, 64, f.key, 0, false);
        if (idx < 0) return false;
        if (i && proposed.front64[i - 1].key >= f.key) return false;
        ctx.f64.push_back(std::make_pair(f.key, idx));
    }
    if (!ctx.ok) return false;

    // Dense, non overlapping coverage of every charged slot.
    for (int s = 0; s < RAM_NUM; ++s) {
        size_t cnt = 0;
        for (size_t c = 0; c < ctx.used[s].size(); ++c) cnt += ctx.used[s][c];
        if (cnt != proposed.cells[s]) return false;
        if (proposed.cells[s] & 1u) {
            const std::bitset<256>& w = proposed.banks[s][proposed.cells[s] >> 1];
            for (int k = 128; k < 256; ++k) if (w[k]) return false;
        }
    }
    // Dictionary and NI vector usage.
    for (size_t i = 0; i < ctx.pat_used.size(); ++i) if (!ctx.pat_used[i]) return false;
    for (size_t i = 0; i < ctx.ni_used.size(); ++i) if (!ctx.ni_used[i]) return false;

    // Rebuild the FIB represented by the image and check every BMP.
    Fib fib;
    uint64_t total = 0;
    for (size_t i = 0; i < ctx.nodes.size(); ++i) {
        const ImageNode& n = ctx.nodes[i];
        for (size_t k = 0; k < n.inlines.size(); ++k) {
            fib.put((uint8_t)(n.origin + n.inlines[k].l), n.inlines[k].hi, n.inlines[k].lo,
                    n.inlines[k].hop);
            ++total;
        }
        if (n.type <= 3) {
            uint64_t p = n.pattern;
            while (p) {
                int b = __builtin_ctzll(p);
                p &= p - 1ull;
                int l = ni_level(b);
                uint64_t v = (uint64_t)b - (1ull << l);
                uint64_t phi = n.reghi, plo = n.reglo;
                set_bits128(phi, plo, n.depth, l, v);
                int off = __builtin_popcountll(n.pattern & (((uint64_t)1 << b) - 1));
                fib.put((uint8_t)(n.depth + l), phi, plo, proposed.nexthops[n.ni_base + off]);
                ++total;
            }
        }
    }
    if (total != fib.size()) return false;  // duplicated prefixes
    if (fib.size() > 8192u) return false;
    for (size_t i = 0; i < ctx.nodes.size(); ++i) {
        const ImageNode& n = ctx.nodes[i];
        uint32_t hop = 0;
        uint64_t want = fib.longest_within((uint8_t)n.depth, n.reghi, n.reglo, hop)
                            ? (uint64_t)hop : IMAGE_BMP_NULL;
        if (n.bmp != want) return false;
    }

    data_ = proposed;
    nodes_.swap(ctx.nodes);
    slots_.swap(ctx.slot);
    root_idx_ = ctx.root_idx;
    front16_.swap(ctx.f16);
    front64_.swap(ctx.f64);
    return true;
}
